 async function runOneSignal(callback){return await new Promise((resolve,reject)=>{if(!window.OneSignalDeferred){reject(Error('Push notifications are not available on this page.'));return;}const timer=setTimeout(()=>reject(Error('Push notifications did not finish loading.')),8000);window.OneSignalDeferred.push(async OneSignal=>{try{resolve(await callback(OneSignal))}catch(error){reject(error)}finally{clearTimeout(timer)}});});}
