 async function setPushStatus(kind,message){const label=$('pushPreferenceStatus');label.className='push-preference-status '+kind;label.textContent=message;}
 async function refreshPushPreference(){const help=$('pushPreferenceHelp'),enable=$('enablePushPreference'),disable=$('disablePushPreference'),quick=$('enablePushFromToolbar');try{const state=await runOneSignal(OneSignal=>({optedIn:OneSignal.User.PushSubscription.optedIn,permission:OneSignal.Notifications.permissionNative,supported:OneSignal.Notifications.isPushSupported()}));if(!state.supported){await setPushStatus('is-unavailable',isAppleMobile?'PUSH NOTIFICATIONS: IPHONE SETUP REQUIRED':'PUSH NOTIFICATIONS: UNAVAILABLE ON THIS BROWSER');help.textContent=isAppleMobile?'On iPhone, web push requires iOS 16.4 or later and GAC added to your Home Screen. Tap the button beside Refresh account for setup steps.':'You can still use your GAC account normally.';enable.hidden=true;disable.hidden=true;quick.hidden=!isAppleMobile;return;}const enabled=state.optedIn===true;quick.hidden=enabled;enable.hidden=enabled;disable.hidden=!enabled;if(enabled){await setPushStatus('is-on','PUSH NOTIFICATIONS: ON · THIS BROWSER IS SUBSCRIBED');help.textContent='You can turn them off anytime here in My profile.';}else if(state.permission==='denied'){await setPushStatus('is-blocked','PUSH NOTIFICATIONS: OFF · BLOCKED IN BROWSER SETTINGS');help.textContent='To turn them on, allow notifications for gacfirearms.com in your browser or device settings, then return here.';}else{await setPushStatus('is-off','PUSH NOTIFICATIONS: OFF · THIS BROWSER IS NOT SUBSCRIBED');help.textContent='Turn them on here, or use the quick button beside Refresh account.';}}catch{await setPushStatus('is-unavailable','PUSH NOTIFICATIONS: STATUS UNAVAILABLE');help.textContent='Refresh the page and try again.';quick.hidden=false;enable.hidden=false;disable.hidden=true;}}
 async function enablePushNotifications(){const iphoneSteps=isAppleMobile?(isAppleHomeScreen()?' On iPhone, notifications for this GAC Home Screen app can also be managed in Settings → Notifications.':' On iPhone, first add GAC to your Home Screen (Safari Share → Add to Home Screen), then open GAC from its icon and tap Turn on notifications. This requires iOS 16.4 or later.') : '';if(!confirm('Turn on GAC push notifications for this browser? You can turn notifications on or off anytime in My profile.'+iphoneSteps))return;const permission=await runOneSignal(OneSignal=>OneSignal.Notifications.permissionNative);if(permission==='denied'){await refreshPushPreference();throw Error('Notifications are blocked by your browser. Allow them for gacfirearms.com in browser or device settings, then try again.');}if(permission!=='granted')await runOneSignal(OneSignal=>OneSignal.Notifications.requestPermission());const updated=await runOneSignal(async OneSignal=>{if(OneSignal.Notifications.permissionNative!=='granted')return false;await OneSignal.User.PushSubscription.optIn();return true;});await refreshPushPreference();if(!updated)throw Error('Notification permission was not granted. You can enable it later in browser settings.');status('Push notifications turned on for this browser.');}
 $('enablePushPreference').onclick=()=>action(enablePushNotifications);$('enablePushFromToolbar').onclick=()=>action(async()=>{if(isAppleMobile&&!isAppleHomeScreen()){alert('To turn on GAC push notifications on your iPhone:\n\n1. Make sure your iPhone is running iOS 16.4 or later.\n2. In Safari, open gacfirearms.com and tap Share → Add to Home Screen.\n3. Open GAC from the new Home Screen icon and sign in.\n4. Tap Turn on notifications and allow notifications.\n\nYou can turn notifications on or off anytime in My profile.');return;}if(isAppleMobile){const state=await runOneSignal(OneSignal=>OneSignal.Notifications.isPushSupported());if(!state){alert('GAC push notifications require iOS 16.4 or later. Update iOS, then open GAC from its Home Screen icon and try again. You can turn notifications on or off anytime in My profile.');return;}}await enablePushNotifications();});
