 async function keepWheelAwake(){
  if(panel!=='live'||document.visibilityState!=='visible')return;
  if(!('wakeLock' in navigator)){$('wheelWakeStatus').textContent='This browser may allow the screen to sleep. You can increase the screen timeout in your phone settings.';return;}
  if(wheelWakeLock&&!wheelWakeLock.released)return;
  if(wheelWakeLockRequest)return wheelWakeLockRequest;
  wheelWakeLockRequest=(async()=>{try{const lock=await navigator.wakeLock.request('screen');if(panel!=='live'||document.visibilityState!=='visible'){await lock.release();return;}wheelWakeLock=lock;lock.addEventListener('release',()=>{if(wheelWakeLock===lock)wheelWakeLock=null;});$('wheelWakeStatus').textContent='';}catch{$('wheelWakeStatus').textContent='The browser could not keep this screen awake. You can increase the screen timeout in your phone settings.';}finally{wheelWakeLockRequest=null;}})();
  return wheelWakeLockRequest;
 }
 function releaseWheelAwake(){const lock=wheelWakeLock;wheelWakeLock=null;if(lock&&!lock.released)lock.release().catch(()=>{});}
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&panel==='live')keepWheelAwake();else if(wheelWakeLock)releaseWheelAwake();});
 function show(key){panel=key;saveView('panel',key);for(const [k,p] of Object.entries(panels))p.hidden=k!==key;admin.hidden=key!=='admin'||!owner;for(const b of nav.querySelectorAll('button'))b.classList.toggle('active',b.dataset.panel===key);for(const b of primaryNav.querySelectorAll('button'))b.classList.toggle('active',b.dataset.panel===key);if(key!=='live'){sharedNotice?.update(null,[],[],Date.now(),false);releaseWheelAwake();}if(key==='live'){keepWheelAwake();poll();}if(key==='orders'&&profile)action(async()=>{if(await loadMemberStoreOrders())await markMemberOrderUpdatesSeen();});if(key==='messages')messageUI?.open();if(key==='profile')refreshPushPreference();}
 function showAdmin(key){ownerPanel=adminNavigation?adminNavigation.show(key):key;saveView('ownerPanel',ownerPanel);if((key==='numberHolds'||ownerPanel==='collections')&&owner){holds?.refreshOwner().catch(e=>status(e.message));manualAssignment?.sync(owner,collections,memberList).catch(e=>status(e.message));}if(ownerPanel==='payments'&&owner)paymentUI?.refreshOwnerCollectionNames?.().catch(e=>status(e.message));if(!adminNavigation){for(const [k,p]of Object.entries(adminPanels))p.hidden=k!==key;for(const b of adminNav.querySelectorAll('button'))b.classList.toggle('active',b.dataset.ownerPanel===key)}}
 function dateLocal(value){if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
 function money(cents){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100)}
 function soldNumberCount(rows){return new Set((rows||[]).map(x=>Number(x.edition_number)).filter(Number.isFinite)).size}
 function displayCollectionState(c){const count=c?collectionSoldCounts.get(c.id):null;return c?.state==='open'&&Number.isFinite(count)&&count>=Number(c.quantity)?'closed':c?.state||''}
 function setSelect(id,items,idValue){const s=$(id);s.replaceChildren();for(const c of items){const o=el('option',(c.is_test?'TEST · ':'')+(c.price_cents===0?'FREE · ':'')+c.callsign+' · '+displayCollectionState(c));o.value=c.id;s.append(o)}s.value=idValue||items[0]?.id||'';if(id==='collectionPick'){const picker=$('callsignPicker');const openCollectionCount=items.filter(c=>{const count=collectionSoldCounts.get(c.id);return collectionIsOpen(c,Date.now()+serverOffset)&&Number.isFinite(count)&&count<Number(c.quantity)}).length;picker?.classList.toggle('has-options',items.length>1&&openCollectionCount>1&&picker.dataset.acknowledged!=='true')}}
 async function loadCollections(){const previous=active?.id;const all=await read(client.from('gac_collections').select('*').order('created_at',{ascending:false}));collections=all.filter(c=>!c.archived_at).sort((a,b)=>Number(!!b.is_featured)-Number(!!a.is_featured)||new Date(b.created_at)-new Date(a.created_at));archivedCollections=owner?all.filter(c=>c.archived_at):[];collectionSoldCounts=new Map(await Promise.all(collections.map(async c=>{try{return[c.id,soldNumberCount(await api.wheelEntries(c.id))]}catch{return[c.id,NaN]}})));if(!collections.some(c=>c.id===active?.id))active=collections[0]||null;else active=collections.find(c=>c.id===active.id);if(previous!==active?.id){$('purchaseAck').checked=false;entries=[];result=null;rounds=[];}setSelect('collectionPick',collections,active?.id);setSelect('ownerGroup',collections,active?.id);renderCollections(true);await artwork();await poll();}
 function renderCollections(updateSettings=false){const c=active;const currentSoldCount=soldNumberCount(entries);if(c)collectionSoldCounts.set(c.id,currentSoldCount);const displayStatus=displayCollectionState(c);setSelect('collectionPick',collections,c?.id);$('collectionSpinBadge').hidden=!c||Number(c.spin_count||1)<2;$('collectionSpinBadge').classList.toggle('is-multispin',!!c&&Number(c.spin_count||1)>1);$('collectionSpinBadge').textContent=c&&Number(c.spin_count||1)>1?Number(c.spin_count)+' SPINS':'';$('collectionDetailsLink').hidden=!c;$('collectionDetailsLink').disabled=!c;$('purchaseAckText').textContent=c?.price_cents===0?purchaseAckStatement.replace(/I am purchasing\b/i,'I am claiming a free'):purchaseAckStatement;$('selectionCheckoutNote').textContent=c?.price_cents===0?'Free numbers are assigned when you claim them. A $0 order is recorded, and the numbers appear on the wheel.':'Number selection is a preview of availability. No payment is collected and no number is reserved until checkout is connected and payment is verified.';$('currentTitle').textContent=c?.callsign||'No collection released yet';$('wheelTitle').textContent=(c?.is_test?'TEST · ':'')+(c?.callsign||'GAC');$('collectionSummary').textContent=c?`${c.is_test?'TEST MODE · owner only · no payment collected · ':''}${c.quantity} numbers · ${c.price_cents===0?'FREE':money(c.price_cents)+' each'} · ${displayStatus} · Release ${new Date(c.release_at).toLocaleString()}`:'Your owner will publish a collection here.';const openSpots=$('ownerOpenSpots');openSpots.hidden=!owner||!c;openSpots.textContent=c?'OPEN SPOTS · '+Math.max(0,Number(c.quantity)-currentSoldCount):'';$('numberGrid').replaceChildren();const sold=new Set(entries.map(x=>x.edition_number));for(let n=1;n<=(c?.quantity||0);n++){const b=el('button',String(n));b.type='button';b.disabled=sold.has(n)||!collectionIsOpen(c,Date.now()+serverOffset);if(b.disabled)b.dataset.locked='true';b.className=sold.has(n)?'sold':selected.has(n)?'chosen':'secondary';holds?.decorate(b,n);$('numberGrid').append(b)}$('selectionSummary').textContent=selected.size?'Selected: '+[...selected].sort((a,b)=>a-b).join(', '):'No numbers selected';$('selectionTotal').textContent=c?money(c.price_cents*selected.size):'';updateCheckout();$('wheelState').querySelector('option[value="recognized"]').disabled=c?.state!=='recognized';$('randomNumber').disabled=!holds?.availableNumbers().length;$('saveGroupTitle').disabled=!owner||!c;$('pinCurrentCollection').disabled=!owner||!c;$('pinCurrentCollection').textContent=c?.is_featured?'Unpin from top of Current collection':'Pin to top on Current collection';$('featuredCollectionStatus').textContent=c?.is_featured?'This collection appears first when Current collection loads.':'Pin this collection to make it the first one shown to members.';renderGroupArchive();if(owner&&c&&updateSettings){$('editGroupTitle').value=c.callsign||'';$('groupDetails').value=c.details||'';$('holdMinutes').value=c.hold_minutes||10;$('spinCount').value=c.spin_count||1;$('spinCount').max=c.quantity;$('spinPause').value=c.spin_pause_seconds||15;$('wheelSchedule').value=dateLocal(c.recognition_at);$('wheelState').value=c.state;for(const id of ['rpm','duration','power','idle'])$(id).value=c.wheel_settings[id];$('automatic').checked=c.auto_spin;$('wheelTest').checked=c.is_test;rangeLabels();$('ownerGroupSummary').textContent=c.state==='recognized'?'Completed recognition settings are locked. Create a new group for a new number pool.':'Create a new group to reset the numbers. This preserves prior records.';}}
 function rangeLabels(){for(const id of ['rpm','duration','idle'])$(id+'Value').textContent=$(id).value+(id==='rpm'?' RPM':id==='duration'?' seconds':' RPM')}
